static bool sha256_bytes(const uint8_t* data,size_t n,uint8_t out[32]){Alg alg;NTSTATUS st=BCryptOpenAlgorithmProvider(&alg.h,BCRYPT_SHA256_ALGORITHM,nullptr,0);if(!BCRYPT_SUCCESS(st))return false;DWORD obj_len=0,cb=0,hash_len=0;st=BCryptGetProperty(alg.h,BCRYPT_OBJECT_LENGTH,(PUCHAR)&obj_len,sizeof(obj_len),&cb,0);if(!BCRYPT_SUCCESS(st)||obj_len==0)return false;st=BCryptGetProperty(alg.h,BCRYPT_HASH_LENGTH,(PUCHAR)&hash_len,sizeof(hash_len),&cb,0);if(!BCRYPT_SUCCESS(st)||hash_len!=32)return false;std::vector<UCHAR> obj(obj_len);Hs hs;st=BCryptCreateHash(alg.h,&hs.h,obj.data(),obj_len,nullptr,0,0);if(!BCRYPT_SUCCESS(st))return false;size_t off=0;while(off<n){size_t chunk=n-off;if(chunk>1048576u)chunk=1048576u;st=BCryptHashData(hs.h,(PUCHAR)data+off,(ULONG)chunk,0);if(!BCRYPT_SUCCESS(st))return false;off+=chunk;}st=BCryptFinishHash(hs.h,out,32,0);return BCRYPT_SUCCESS(st);}
static bool sha256_file(const wchar_t* path,uint64_t& sz,uint8_t out[32],const char*& err){err="cannot_open";File f;f.h=CreateFileW(path,GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL|FILE_FLAG_SEQUENTIAL_SCAN,nullptr);if(f.h==INVALID_HANDLE_VALUE)return false;LARGE_INTEGER li{};if(!GetFileSizeEx(f.h,&li)){err="size_query_failed";return false;}if(li.QuadPart<0){err="size_query_failed";return false;}sz=(uint64_t)li.QuadPart;if(sz!=kSize){err="size_mismatch";return false;}Alg alg;NTSTATUS st=BCryptOpenAlgorithmProvider(&alg.h,BCRYPT_SHA256_ALGORITHM,nullptr,0);if(!BCRYPT_SUCCESS(st)){err="bcrypt_open_failed";return false;}DWORD obj_len=0,cb=0,hash_len=0;st=BCryptGetProperty(alg.h,BCRYPT_OBJECT_LENGTH,(PUCHAR)&obj_len,sizeof(obj_len),&cb,0);if(!BCRYPT_SUCCESS(st)||obj_len==0){err="bcrypt_object_length_failed";return false;}st=BCryptGetProperty(alg.h,BCRYPT_HASH_LENGTH,(PUCHAR)&hash_len,sizeof(hash_len),&cb,0);if(!BCRYPT_SUCCESS(st)||hash_len!=32){err="bcrypt_hash_length_failed";return false;}std::vector<UCHAR> obj(obj_len);Hs hs;st=BCryptCreateHash(alg.h,&hs.h,obj.data(),obj_len,nullptr,0,0);if(!BCRYPT_SUCCESS(st)){err="bcrypt_create_failed";return false;}uint64_t got=0;uint8_t buf[1<<16];while(got<sz){uint64_t remain=sz-got;DWORD want=remain>sizeof(buf)?(DWORD)sizeof(buf):(DWORD)remain;DWORD rd=0;if(!ReadFile(f.h,buf,want,&rd,nullptr)||rd==0){err="short_read";return false;}st=BCryptHashData(hs.h,buf,rd,0);if(!BCRYPT_SUCCESS(st)){err="bcrypt_hash_data_failed";return false;}got+=rd;}if(got!=sz){err="short_read";return false;}st=BCryptFinishHash(hs.h,out,32,0);if(!BCRYPT_SUCCESS(st)){err="bcrypt_finish_failed";return false;}err="";return true;}
struct Cmp{bool length_ok=false,all_finite_ref=false,all_finite_tgt=false,metrics_ok=false;double max_abs=0,rmse=0;int fail_count=0;};
static Cmp compare_logits(const float* r,size_t nr,const float* t,size_t nt,float atol,float rtol){Cmp c;c.length_ok=r&&t&&nr==nt&&nr>0;c.all_finite_ref=true;c.all_finite_tgt=true;if(!c.length_ok){c.fail_count=1;return c;}double sum=0,mx=0;int fc=0;for(size_t i=0;i<nr;i++){bool fr=std::isfinite(r[i]),ft=std::isfinite(t[i]);if(!fr)c.all_finite_ref=false;if(!ft)c.all_finite_tgt=false;if(!fr||!ft)continue;double d=std::fabs((double)r[i]-(double)t[i]);double tol=(double)atol+(double)rtol*std::fabs((double)r[i]);if(d>tol)fc++;if(d>mx)mx=d;sum+=d*d;}c.fail_count=fc;c.metrics_ok=c.all_finite_ref&&c.all_finite_tgt;if(c.metrics_ok){c.max_abs=mx;c.rmse=std::sqrt(sum/(double)nr);}return c;}
