int qual_self_test(){int fails=0;std::string names;auto exp=[&](bool cond,const char* n){if(!cond){fails++;if(!names.empty())names+=",";names+="\"";names+=n;names+="\"";}};float a[]={1.f,2.f,3.f,4.f};float b[]={1.005f,2.005f,3.005f,4.005f};Cmp c=compare_logits(a,4,b,4,0.01f,0.01f);exp(c.metrics_ok&&c.fail_count==0,"within_tol");float nan=std::numeric_limits<float>::quiet_NaN();float inf=std::numeric_limits<float>::infinity();float rn[]={1.f,nan,3.f};float tn[]={1.f,2.f,3.f};c=compare_logits(rn,3,tn,3,0.01f,0.01f);exp(!c.all_finite_ref&&!c.metrics_ok,"nan_ref");float ri[]={1.f,2.f,3.f};float ti[]={1.f,inf,3.f};c=compare_logits(ri,3,ti,3,0.01f,0.01f);exp(!c.all_finite_tgt&&!c.metrics_ok,"inf_tgt");float rp[]={1.f,2.f};float tp[]={1.05f,2.f};c=compare_logits(rp,2,tp,2,0.01f,0.01f);exp(c.metrics_ok&&c.fail_count==1,"perturb");c=compare_logits(a,4,b,3,0.01f,0.01f);exp(!c.length_ok&&!c.metrics_ok,"length");c=compare_logits(a,0,b,0,0.01f,0.01f);exp(!c.length_ok,"empty");float big0[]={100.f};float big1[]={101.f};float big2[]={101.02f};exp(compare_logits(big0,1,big1,1,0.01f,0.01f).fail_count==0,"rtol_pass");exp(compare_logits(big0,1,big2,1,0.01f,0.01f).fail_count==1,"rtol_fail");std::vector<float> cpu{1.f,2.f},gpu{1.f,2.f},cpu0=cpu;corrupt_gpu_only(gpu,cpu);exp(cpu==cpu0,"cpu_unmodified");exp(compare_logits(cpu.data(),cpu.size(),gpu.data(),gpu.size(),0.01f,0.01f).fail_count>0,"inject_fails");std::string in;in.push_back('a');in.push_back('"');in.push_back('\\');in.push_back('\n');in.push_back(1);std::string e=esc(in);exp(e.find("\\\"")!=std::string::npos&&e.find("\\n")!=std::string::npos&&e.find("\\u0001")!=std::string::npos,"esc");exp(num_or_null(false,1.0)=="null"&&num_or_null(true,nan)=="null"&&num_or_null(true,1.5).find("nan")==std::string::npos,"num_null");uint8_t h[32]{};const uint8_t abc[]={'a','b','c'};exp(sha256_bytes(abc,3,h)&&hex32(h)=="ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad","sha256_abc");std::string o="{\"self_test\":true,\"status\":\"";