string esc(const string& s ) {
    string r;
    r.reserve(s.size() + 8);
    for (unsigned char c : s) {
        if (c == '"') r += "\"";
        else if (c == '\\') r += "\\\\";
        else if (c == '\n') r += "\\n";
        else if (c == '\r') r += "\\r";
        else if (c == '\t') r += "\\t";
        else if (c < 0x20) {
            char b[8];
            snprintf (b, 8, "\\u%04x", c);
            r += b;
        } else r += (char)c;
    }
    return r;
}

string hex32(const uint8_t h[32]) {
    string s(64, '0 ');
    for (int i = 0; i < 32; i++) {
        s[i*2] = "0123456789abcdef"[h[i] >> 4];
        s[i*2+1] = "0123456789abcdef"[h[i] & 0xf];
    }
    return s;
}

