    BCRYPT_ALG_HANDLE alg = nullptr;
    BCRYPT_HASH_HANDLE h = nullptr;
    NT STATUS st = BCryptOpenAlgorithmProvider(&alg, BCRYPT_SHA256_ALGORITHM, nullptr, 0);
    if (!BCRYPT_SUCCESS(st)) return false;
    DWORD obj_len = 0;
    DWORD cb = 0;
    st = BCryptGetProperty(alg, B C R Y P T _ O B J E C T _ L E N G T H, (PUCHAR)&obj_len, sizeof(obj_len), &cb, 0);
    if (!BCRYPT_SUCCESS(st) || obj_len == 0) {
        BCryptCloseAlgorithmProvider(alg, 0);
        return false;
    }
    DWORD hash_len = 0;
    st = BCryptGetProperty(alg, BCRYPT_HASH_LENGTH, (PUCHAR)&hash_len, sizeof(hash_len), &cb, 0);
    if (!BCRYPT_SUCCESS(st) || hash_len != 32) {
